#[cfg(test)]mod console_attachment_tests{
 use super::*;use std::io::Read;use std::sync::mpsc;
 #[test]fn console_fixture_child(){
  if std::env::var_os("VIVIM_CONPTY_FIXTURE").is_none(){return;}
  use windows_sys::Win32::{Storage::FileSystem::{CreateFileW,OPEN_EXISTING,FILE_SHARE_READ,FILE_SHARE_WRITE},System::Console::{GetConsoleMode,WriteConsoleW},Foundation::{GENERIC_WRITE,INVALID_HANDLE_VALUE}};
  let name:Vec<u16>="CONOUT$".encode_utf16().chain(Some(0)).collect();
  let raw=unsafe{CreateFileW(name.as_ptr(),GENERIC_WRITE,FILE_SHARE_READ|FILE_SHARE_WRITE,null(),OPEN_EXISTING,0,null_mut())};
  assert_ne!(raw,INVALID_HANDLE_VALUE,"no console output handle");
  let handle=unsafe{own(raw)};let mut mode=0;
  assert_ne!(unsafe{GetConsoleMode(super::raw(&handle),&mut mode)},0,"not a console handle");
  let marker:Vec<u16>="VIVIM_CONPTY_NATIVE_MARKER\r\n".encode_utf16().collect();let mut written=0;
  assert_ne!(unsafe{WriteConsoleW(super::raw(&handle),marker.as_ptr().cast(),marker.len() as u32,&mut written,null_mut())},0);
  assert_eq!(written,marker.len() as u32);
 }
 #[test]fn real_owned_child_attached(){
  let exe=std::env::current_exe().unwrap();let cwd=std::env::current_dir().unwrap();
  let mut env=vec![("VIVIM_CONPTY_FIXTURE".into(),"1".into())];if let Some(root)=std::env::var_os("SystemRoot"){env.push(("SystemRoot".into(),root));}
  let args:Vec<OsString>=["console_fixture_child","--nocapture","--test-threads=1"].into_iter().map(Into::into).collect();
  let (mut p,input,mut output)=Process::spawn_console(&exe,&cwd,&args,&env,Size{columns:80,rows:24}).unwrap();
  let(tx,rx)=mpsc::channel();let reader=thread::spawn(move||{let mut bytes=Vec::new();let r=output.read_to_end(&mut bytes);let _=tx.send((r,bytes));});
  p.resize_console(Size{columns:100,rows:30}).unwrap();
  let start=Instant::now();let status=loop{if let Some(s)=p.try_wait().unwrap(){break s;}if start.elapsed()>Duration::from_secs(10){p.kill().unwrap();let _=p.wait();panic!("owned PTY child did not settle");}thread::sleep(Duration::from_millis(20));};
  drop(input);p.finish_console().unwrap();
  let(r,bytes)=rx.recv_timeout(Duration::from_secs(5)).unwrap();r.unwrap();reader.join().unwrap();
  let observed=String::from_utf8_lossy(&bytes);
  assert!(status.success(),"fixture exit {:?}; output {:?}",status.code(),observed);
  assert!(observed.contains("VIVIM_CONPTY_NATIVE_MARKER"),"PTY bytes {:?}; observed {:?}",bytes.len(),observed);
 }
